// 対象Threadsアカウント（ユーザーID）
// ユーザーIDは Threads API で取得
// 例: https://www.threads.net/@username のIDをAPIで取得する
const targetAccounts = [
  { username: 'chroniki_claude', userId: 'THREADS_USER_ID_1', description: 'Claude Code専門家' },
  { username: 'ai_trend_jp', userId: 'THREADS_USER_ID_2', description: 'AIトレンド情報' },
  { username: 'prompt_engineering_jp', userId: 'THREADS_USER_ID_3', description: 'プロンプトエンジニアリング' }
];

// 3時間前のタイムスタンプ
const threeHoursAgo = Math.floor((Date.now() - 3 * 60 * 60 * 1000) / 1000);

return targetAccounts.map(acc => ({
  json: {
    username: acc.username,
    userId: acc.userId,
    description: acc.description,
    since: threeHoursAgo
  }
}));

// Threadsレスポンスを整形
const posts = $json.data || [];
if (posts.length === 0) {
  return [{ json: { skip: true } }];
}

// AI関連キーワードフィルタ
const aiKeywords = ['AI', 'Claude', 'GPT', 'ChatGPT', 'Gemini', '人工知能', '機械学習', 'プロンプト', 'LLM', '生成AI', 'Anthropic', 'OpenAI'];

const aiPosts = posts.filter(post => {
  const text = post.text || '';
  return aiKeywords.some(kw => text.toLowerCase().includes(kw.toLowerCase()));
});

if (aiPosts.length === 0) {
  return [{ json: { skip: true } }];
}

// 全投稿をまとめて1つの記事にする
const username = $('対象アカウント設定').item.json.username;
const postsText = aiPosts.map(p => `- ${p.text} (${p.permalink})`).join('\n');

return [{
  json: {
    username: username,
    postCount: aiPosts.length,
    postsText: postsText,
    posts: aiPosts
  }
}];

const content = $json.content[0].text;
const threadsData = $('AI関連投稿をフィルタリング').item.json;

return [{
  json: {
    title: `【Threads】@${threadsData.username}のAIノウハウまとめ（${threadsData.postCount}件）`,
    content: content,
    status: 'draft'
  }
}];
